%% Style rules for `rebar3 lint'. Formatting proper (indentation, line
%% breaks, spacing) is owned by erlfmt — the rules here cover the things a
%% formatter cannot check: naming, module size, nesting depth, and common
%% correctness smells.
[
    {elvis, [
        {config, [
            #{
                dirs => ["src"],
                filter => "*.erl",
                ruleset => erl_files,
                rules => [
                    %% erlfmt's print width is 96; allow a little slack for
                    %% long spec lines it will not break.
                    {elvis_text_style, line_length, #{limit => 100}},
                    %% The dispatcher and the transports legitimately hold a
                    %% double-digit number of small internal functions.
                    {elvis_style, god_modules, #{limit => 40}},
                    %% Macros for JSON-RPC error codes are numeric constants,
                    %% which is exactly what macros are for.
                    {elvis_style, no_macros, disable},
                    %% `?MODULE' as an ETS/registered name is idiomatic OTP.
                    {elvis_style, dont_repeat_yourself, #{min_complexity => 15}}
                ]
            },
            #{
                dirs => ["test"],
                filter => "*.erl",
                ruleset => erl_files,
                rules => [
                    {elvis_text_style, line_length, #{limit => 100}},
                    {elvis_style, god_modules, disable},
                    {elvis_style, no_macros, disable},
                    {elvis_style, dont_repeat_yourself, disable},
                    %% Test suites export one function per case by design.
                    {elvis_style, no_call, disable}
                ]
            },
            #{
                dirs => ["."],
                filter => "rebar.config",
                ruleset => rebar_config
            }
        ]}
    ]}
].

